const body = $json.body ?? $json;
const hoy = $now.setZone('Europe/Madrid').startOf('day');
const fmt = d => d.toFormat('yyyy-MM-dd');
const txt = v => String(v ?? '').trim();
const reFecha = /^\d{4}-\d{2}-\d{2}$/;
const num = v => { const s = txt(v).replace(',', '.'); const n = Number(s); return (s === '' || !Number.isFinite(n)) ? null : n; };
const bool = v => [true, 'true', 1, '1', 'si', 'sí'].includes(typeof v === 'string' ? v.trim().toLowerCase() : v);

let desde = txt(body.fecha_inicio);
let hasta = txt(body.fecha_final);
const periodo = txt(body.periodo).toLowerCase();

if (!desde && !hasta) {
  if (periodo === 'ayer') { desde = hasta = fmt(hoy.minus({ days: 1 })); }
  else if (periodo === 'semana') { desde = fmt(hoy.startOf('week')); hasta = fmt(hoy.startOf('week').plus({ days: 6 })); }
  else if (periodo === 'semana_pasada') { desde = fmt(hoy.startOf('week').minus({ days: 7 })); hasta = fmt(hoy.startOf('week').minus({ days: 1 })); }
  else if (periodo === 'mes') { desde = fmt(hoy.startOf('month')); hasta = fmt(hoy.endOf('month')); }
  else if (periodo === 'mes_pasado') { const m = hoy.minus({ months: 1 }); desde = fmt(m.startOf('month')); hasta = fmt(m.endOf('month')); }
  else { desde = hasta = fmt(hoy); }
}
if (!desde) desde = hasta;
if (!hasta) hasta = desde;

if (!reFecha.test(desde) || !reFecha.test(hasta)) {
  throw new Error('Fechas no validas: usa formato AAAA-MM-DD (fecha_inicio, fecha_final) o periodo = hoy | ayer | semana | semana_pasada | mes | mes_pasado');
}
if (desde > hasta) { const t = desde; desde = hasta; hasta = t; }
const dias = Math.round((new Date(hasta) - new Date(desde)) / 86400000) + 1;
if (dias > 93) {
  throw new Error('Rango demasiado grande (' + dias + ' dias): el maximo son 93 dias por consulta');
}

let por = txt(body.por).toLowerCase() || 'carga';
if (!/^[a-z]{1,20}$/.test(por)) por = 'carga';

const cerradoTxt = txt(body.cerrado);

return [{ json: {
  fecha_inicio: desde,
  fecha_final: hasta,
  por,
  detalle: bool(body.detalle),
  vacios: bool(body.vacios),
  limite: Math.min(Math.max(parseInt(body.limite, 10) || 100, 1), 300),
  filtros: {
    cliente: txt(body.cliente),
    matricula: txt(body.matricula),
    conductor: txt(body.conductor),
    transportista: txt(body.transportista),
    numero_pedido: txt(body.numero_pedido),
    origen: txt(body.origen),
    destino: txt(body.destino),
    comercial: txt(body.comercial),
    buscar: txt(body.buscar),
    km_min: num(body.km_min),
    km_max: num(body.km_max),
    importe_min: num(body.importe_min),
    importe_max: num(body.importe_max),
    sin_asignar: bool(body.sin_asignar),
    cerrado: cerradoTxt === '' ? null : bool(body.cerrado)
  }
} }];

const prm = $('Preparar parametros').first().json;
const r = $input.first()?.json;

if (!r || r.error || !Array.isArray(r.pedidos)) {
  const e = r?.error;
  const detalle = e ? (typeof e === 'string' ? e : [e.message, e.description].filter(Boolean).join(' - ')) : 'respuesta inesperada';
  throw new Error('No se han podido consultar los pedidos en T2000: ' + String(detalle).slice(0, 300));
}

const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const unicos = a => [...new Set(a.map(x => String(x ?? '').trim()).filter(Boolean))];
const r2 = n => Math.round(n * 100) / 100;
const numero = v => (v === null || v === undefined || v === '') ? null : (Number.isFinite(Number(v)) ? Number(v) : null);
const esc = o => Object.fromEntries(Object.entries(o).filter(([, v]) => v === null || typeof v !== 'object'));
const CERO = ['IntercambioPalets', 'Palets', 'HayTemperatura', 'Temperatura', 'HayTemperatura2', 'Temperatura2'];
const compacto = o => {
  const out = {};
  for (const [k, v] of Object.entries(o)) {
    if (v === null || v === '') continue;
    if (CERO.includes(k) && (v === '0' || v === '0.0')) continue;
    out[k] = v;
  }
  return out;
};
const movs = p => Array.isArray(p.movimientos) ? p.movimientos : [];
const estado = (arr, k) => arr.length === 0 ? 'sin movimientos' : (arr.every(m => String(m[k]) === '1') ? 'si' : (arr.some(m => String(m[k]) === '1') ? 'parcial' : 'no'));

const f = prm.filtros;
const q = {};
for (const k of ['cliente', 'matricula', 'conductor', 'transportista', 'numero_pedido', 'origen', 'destino', 'comercial', 'buscar']) q[k] = norm(f[k]);

const coincide = (p) => {
  const mv = movs(p);
  if (q.cliente && !norm(p.NombreCliente + ' ' + p.Cliente).includes(q.cliente)) return false;
  if (q.matricula && !norm([p.MatriculaVehiculo, p.MatriculaRemolque, ...mv.flatMap(m => [m.MatriculaVehiculo, m.MatriculaRemolque])].join(' ')).includes(q.matricula)) return false;
  if (q.conductor && !norm(mv.flatMap(m => [m.NombreConductor, m.NombreConductor2]).join(' ')).includes(q.conductor)) return false;
  if (q.transportista && !norm(mv.map(m => m.NombreTransportista).join(' ')).includes(q.transportista)) return false;
  if (q.numero_pedido && !norm([p.NumeroPedido, p.NumPedCliente, p.ReferenciaCliente, p.NumAlbaranCliente, p.Albaran].join(' ')).includes(q.numero_pedido)) return false;
  if (q.origen && !norm(p.Origen).includes(q.origen)) return false;
  if (q.destino && !norm(p.Destino).includes(q.destino)) return false;
  if (q.comercial && !norm(p.Comercial).includes(q.comercial)) return false;
  if (q.buscar && !norm(JSON.stringify(p)).includes(q.buscar)) return false;
  const km = numero(p.Kilometros) ?? 0;
  if (f.km_min !== null && km < f.km_min) return false;
  if (f.km_max !== null && km > f.km_max) return false;
  const imp = numero(p.Importe) ?? 0;
  if (f.importe_min !== null && imp < f.importe_min) return false;
  if (f.importe_max !== null && imp > f.importe_max) return false;
  if (f.sin_asignar && String(p.MatriculaVehiculo ?? '').trim()) return false;
  if (f.cerrado !== null && (String(p.Cerrado) === '1') !== f.cerrado) return false;
  return true;
};

const filtrados = r.pedidos
  .filter(coincide)
  .sort((a, b) => String(b.FechaCarga ?? '').localeCompare(String(a.FechaCarga ?? '')));

const fila = (p) => {
  const mv = movs(p);
  const o = esc(p);
  o.Importe = numero(p.Importe);
  o.Cerrado = String(p.Cerrado) === '1';
  o.Conductores = unicos(mv.flatMap(m => [m.NombreConductor, m.NombreConductor2])).join(', ');
  o.Transportistas = unicos(mv.map(m => m.NombreTransportista)).join(', ');
  o.KmTeoricosMovimientos = mv.reduce((a, m) => a + (numero(m.KilometrosTeoricos) ?? 0), 0);
  o.NumMovimientos = mv.length;
  o.MovCargado = estado(mv, 'Cargado');
  o.MovTerminado = estado(mv, 'Terminado');
  o.MovConfirmado = estado(mv, 'Confirmado');
  return compacto(o);
};

const LIMITE_DETALLE = 10;
const limite = prm.detalle ? LIMITE_DETALLE : prm.limite;
const mostrados = filtrados.slice(0, limite);
const pedidos = prm.detalle ? mostrados : mostrados.map(fila);

const porCliente = {};
const porTipoServicio = {};
const porTipoPedido = {};
for (const p of filtrados) {
  const k = p.NombreCliente || 'Sin cliente';
  porCliente[k] = porCliente[k] || { cliente: k, pedidos: 0, importe: 0, km: 0 };
  porCliente[k].pedidos += 1;
  porCliente[k].importe = r2(porCliente[k].importe + (numero(p.Importe) ?? 0));
  porCliente[k].km += numero(p.Kilometros) ?? 0;
  const ts = p.TipoServicio || 'sin tipo';
  porTipoServicio[ts] = (porTipoServicio[ts] || 0) + 1;
  const tp = p.TipoPedido || 'sin tipo';
  porTipoPedido[tp] = (porTipoPedido[tp] || 0) + 1;
}
const clientes = Object.values(porCliente).sort((a, b) => b.pedidos - a.pedidos).slice(0, 15);

const resumen = {
  desde: prm.fecha_inicio,
  hasta: prm.fecha_final,
  por: prm.por,
  filtros: Object.fromEntries(Object.entries(f).filter(([, v]) => v !== '' && v !== false && v !== null)),
  pedidos_en_periodo: r.pedidos.length,
  pedidos_tras_filtros: filtrados.length,
  mostrados: mostrados.length,
  truncado: filtrados.length > mostrados.length,
  sin_matricula: filtrados.filter(p => !String(p.MatriculaVehiculo ?? '').trim()).length,
  con_0_km: filtrados.filter(p => !(numero(p.Kilometros) ?? 0)).length,
  km_total: filtrados.reduce((a, p) => a + (numero(p.Kilometros) ?? 0), 0),
  importe_total: r2(filtrados.reduce((a, p) => a + (numero(p.Importe) ?? 0), 0)),
  por_tipo_servicio: porTipoServicio,
  por_tipo_pedido: porTipoPedido,
  por_cliente: clientes
};

const salida = { resumen, pedidos };
salida.nota = prm.detalle
  ? 'Detalle completo tal como lo devuelve T2000 (incluye cargas_descargas, trayectos y movimientos). Maximo ' + LIMITE_DETALLE + ' pedidos.'
  : 'Todos los campos escalares del pedido tal como los devuelve T2000. Un campo ausente significa vacio, nulo o 0 (excepto Kilometros e Importe, que siempre aparecen). Para ver cargas, descargas, trayectos y movimientos completos de un pedido, repite la consulta con detalle=true y su numero_pedido.';

if (prm.vacios) {
  const vac = Array.isArray(r.movimientos_vacio) ? r.movimientos_vacio : [];
  const sel = vac.filter(m => {
    if (q.matricula && !norm(m.MatriculaVehiculo + ' ' + m.MatriculaRemolque).includes(q.matricula)) return false;
    if (q.conductor && !norm(m.NombreConductor + ' ' + m.NombreConductor2).includes(q.conductor)) return false;
    if (q.transportista && !norm(m.NombreTransportista).includes(q.transportista)) return false;
    if (q.buscar && !norm(JSON.stringify(m)).includes(q.buscar)) return false;
    return true;
  });
  salida.movimientos_vacio = sel.slice(0, prm.limite).map(m => compacto(esc(m)));
  salida.resumen.movimientos_vacio_total = sel.length;
}

return [{ json: salida }];
